INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0a79eb84-1d9a-52ce-a501-70cd96622c49','TEXT','A Lantern for the Jetty','Amara liked helping at the sea fog, especially when there was a small job that nobody had planned. One Thursday, Amara noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('91d093d6-819e-5db5-94dc-3ce6559f3da5','TEXT','The Seed Library — A Different Day','Kai liked helping at the community garden, especially when there was a small job that nobody had planned. One Tuesday, Kai noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
