INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0d47e877-5118-5d27-95f6-a476e0037409','TEXT','The Paper Kite Map — A Different Day','Arun liked helping at the open oval, especially when there was a small job that nobody had planned. One Wednesday, Arun noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
