INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('5aa76970-6a1e-549f-8ae7-a64d92cb6aa4','TEXT','The Paper Kite Map','Arun liked helping at the open oval, especially when there was a small job that nobody had planned. One Saturday, Arun noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('3a31ff87-18bf-5629-9f62-44cebb1d89d7','TEXT','The Night Garden List — A Different Day','Sienna liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Wednesday, Sienna noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
