INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fe23527f-37b1-5a68-9b46-fff085b45881','TEXT','The Night Garden List','Sienna liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Saturday, Sienna noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
