INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('951969c2-b941-547d-8563-3d147090c2de','TEXT','The Tiny Ferry — A Different Day','Ruby liked helping at the river workshop, especially when there was a small job that nobody had planned. One Saturday, Ruby noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
