INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('aed06010-fc1b-512a-817d-ed927b790ade','TEXT','The Bicycle Bell Project','Luca liked helping at the bike path, especially when there was a small job that nobody had planned. One Wednesday, Luca noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('f290f11d-61fc-559d-a4a2-23ec675de1c7','TEXT','The Orange Tree Calendar — A Different Day','Zoe liked helping at the school orchard, especially when there was a small job that nobody had planned. One Thursday, Zoe noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
INSERT INTO testlets (id,section_id,stimulus_id,title,testlet_order,is_branching_node,navigation_locked,calculator_allowed,instructions) VALUES ('2bef8a71-2d5a-57ef-be4a-8923b6fe667b','d0016523-e4f0-58c6-ae02-e240ab8aa888','aed06010-fc1b-512a-817d-ed927b790ade','F',8,TRUE,FALSE,NULL,'Complete this F testlet. Answer every question before continuing.');
